namespace KronosScreenRemote;

using System.IO;
using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;

// Kronos factory Program reference (timbre bank code, index) -> the Nautilus factory Program that
// replaces it in a converted Combi. Generated by Nautilus Research/scripts/build_program_ref_map.py
// from both platforms' factory PRELOAD.PCG files: Korg's own choice where its Nautilus port of the
// same factory Combi makes one clear (source "korg"), otherwise a unique-name match ("name").
// Embedded as Resources/KronosToNautilusProgramRefs.json; a file of that name beside the exe overrides it.
sealed class ProgramRefMap
{
    public sealed record Entry(
        [property: JsonPropertyName("kronos_bank")] int KronosBank,
        [property: JsonPropertyName("kronos_index")] int KronosIndex,
        [property: JsonPropertyName("kronos_name")] string KronosName,
        [property: JsonPropertyName("nautilus_bank")] int NautilusBank,
        [property: JsonPropertyName("nautilus_index")] int NautilusIndex,
        [property: JsonPropertyName("nautilus_name")] string NautilusName,
        [property: JsonPropertyName("source")] string Source);

    readonly Dictionary<(int Bank, int Index), Entry> _byKronos = new();
    public int Count => _byKronos.Count;
    public Entry? For(int bank, int index) => _byKronos.GetValueOrDefault((bank, index));

    public static string OverridePath => Path.Combine(Storage.DataDir, "KronosToNautilusProgramRefs.json");
    public static readonly ProgramRefMap Empty = new();

    public static ProgramRefMap FromJson(string json)
    {
        var map = new ProgramRefMap();
        foreach (var e in JsonSerializer.Deserialize<List<Entry>>(json) ?? new())
            map._byKronos[(e.KronosBank, e.KronosIndex)] = e;
        return map;
    }

    public static ProgramRefMap FromCatalog()
    {
        try
        {
            if (File.Exists(OverridePath)) return FromJson(File.ReadAllText(OverridePath));
            var asm = Assembly.GetExecutingAssembly();
            string? name = asm.GetManifestResourceNames().FirstOrDefault(n => n.EndsWith(".KronosToNautilusProgramRefs.json", StringComparison.Ordinal));
            if (name == null) return Empty;
            using var stream = asm.GetManifestResourceStream(name);
            if (stream == null) return Empty;
            using var reader = new StreamReader(stream);
            return FromJson(reader.ReadToEnd());
        }
        catch (Exception ex)
        {
            AppLog.Warn($"[program-ref-map] load failed: {ex.Message}");
            return Empty;
        }
    }

    // Timbre bank code -> the label both instruments show (INT A-F, user banks from 17).
    public static string KronosLabel(int bank, int index) => bank switch
    {
        <= 5 => $"I-{(char)('A' + bank)}{index:000}",
        >= 17 and <= 23 => $"U-{(char)('A' + bank - 17)}{index:000}",
        >= 24 and <= 30 => $"U-{new string((char)('A' + bank - 24), 2)}{index:000}",
        _ => $"bank {bank}:{index:000}",
    };
    public static string NautilusLabel(int bank, int index) => bank switch
    {
        <= 5 => $"{(char)('A' + bank)}{index:000}",
        >= 17 and <= 30 => $"{(char)('G' + bank - 17)}{index:000}",
        _ => $"bank {bank}:{index:000}",
    };
}
